ValidationRule.errorConditionFormula:
AND(
$Setup.Salesforce_Library_Settings__c.Disable_VRs__c = false,
OR(
RecordType.DeveloperName = 'Customer_Complaint',
RecordType.DeveloperName = 'Non_Customer_Complaint'
),

AND(
 NOT( ISNEW() ),
 OR(
  AND(
   IDR_Real_Form_Req__c, 
   ISBLANK( IDR_Real_Form_Ref_No__c )
  ) , 
  AND(
   NOT(IDR_Real_Form_Req__c),
   NOT(ISBLANK( IDR_Real_Form_Ref_No__c )
  )
 )
)
)
)
